/**
 * pblite: Google's "protobuf lite" JSON encoding. A message is a JSON array in
 * which the value of field N sits at index N-1 and unset fields are null.
 *
 * Faithful port of go.mau.fi/util/pblite v0.9.10 (serialize.go,
 * deserialize.go) on top of protobuf-es reflection. Parity is checked against
 * fixtures generated by the Go reference (tools/vectors/pblite).
 *
 * Encoding (Go `SerializeToSlice` + `encoding/json`):
 * - The array length is the highest field number declared on the message.
 * - A field is written only when it is set in the Go `Has` sense: proto3
 *   implicit-presence scalars when non-zero, explicit-presence (`optional`)
 *   and oneof members when present, messages when present (an empty message
 *   is an all-null array), lists when non-empty.
 * - Messages become nested arrays, or base64 (std, padded) of their binary
 *   protobuf when the field has `(pblite.pblite_binary) = true`. pblite_binary
 *   strings become base64 of their UTF-8 bytes.
 * - bytes become base64; 32-bit ints, enums and floats become JSON numbers;
 *   64-bit ints become JSON numbers with exact digits (bigint in `serialize`).
 * - JSON text matches Go byte for byte: no whitespace, and `<`, `>`, `&`,
 *   U+2028 and U+2029 escaped as `\u003c` etc.
 *
 * Decoding (Go `Unmarshal`): ints accept JSON numbers or decimal strings,
 * bools accept booleans or numbers (non-zero is true), enums accept numbers,
 * nulls and indexes beyond the descriptor are ignored, and type mismatches are
 * returned as errors naming the field and its index.
 *
 * Deviations, all unreachable for well-formed traffic:
 * - Go converts out-of-range JSON numbers to ints with implementation-defined
 *   results; this port reproduces Go on amd64 (the fixture generator's arch).
 * - Go keeps invalid UTF-8 from a decoded pblite_binary string as raw bytes;
 *   JS strings cannot, so it is replaced with U+FFFD. Lone surrogates in JS
 *   strings are likewise written as U+FFFD, which is what their UTF-8
 *   (`toBinary`) form decodes to in Go.
 * - Go panics on map fields; this port returns or throws
 *   `PbliteUnsupportedFieldError` (no gmproto message has a map).
 * - Encoding errors are thrown (Go returns them) because they only arise from
 *   schema kinds pblite cannot represent, NaN/Infinity floats, or integer and
 *   enum values Go's types cannot hold (fractions, out of range), never from
 *   data received over the wire. -0 in integer and enum fields is written as
 *   0, as Go's integers have no -0.
 * - pblite_binary sub-messages are encoded with protobuf-es `toBinary`, which
 *   orders oneof members by field number where Go may not. The bytes decode
 *   to the same message; no gmproto pblite_binary message has a oneof.
 */
import {
  create,
  fromBinary,
  getOption,
  ScalarType,
  toBinary,
  type DescField,
  type DescMessage,
  type MessageShape,
} from "@bufbuild/protobuf";
import {
  isReflectMessage,
  reflect,
  reflectList,
  type ReflectMessage,
} from "@bufbuild/protobuf/reflect";
import { base64Decode, base64Encode } from "@bufbuild/protobuf/wire";
import { Result, TaggedError } from "better-result";

import { pblite_binary } from "@/gen/gmproto/vendor/pblite_pb";

/** A value inside a serialized pblite message. 64-bit integers are bigint. */
export type PbliteValue =
  | null
  | boolean
  | number
  | bigint
  | string
  | readonly PbliteValue[];

/** A serialized pblite message: index N-1 holds field N. */
export type Pblite = PbliteValue[];

/** The pblite text was not a JSON array (invalid JSON or another JSON type). */
export class PbliteJsonError extends TaggedError("PbliteJsonError")<{
  message: string;
}> {}

/**
 * A value in the pblite array does not fit its field. `field` is the field's
 * full protobuf name; `index` is the value's position in its enclosing array
 * (field number - 1, or the element position inside a repeated field), as in
 * the Go error. Errors in nested messages name the nested field.
 */
export class PbliteFieldError extends TaggedError("PbliteFieldError")<{
  field: string;
  index: number;
  expected: string;
  got: string;
  message: string;
  cause?: unknown;
}> {}

/** The field's protobuf kind (map, group, sint/fixed ints) has no pblite form. */
export class PbliteUnsupportedFieldError extends TaggedError(
  "PbliteUnsupportedFieldError",
)<{
  field: string;
  fieldType: string;
  message: string;
}> {}

/**
 * A field holds a value pblite cannot encode: a float or double that is NaN or
 * ±Infinity (JSON cannot carry it), or an integer or enum value that is not a
 * whole number within its protobuf type's range (Go cannot hold it, and
 * protobuf-es `toBinary` rejects it too).
 */
export class PbliteUnsupportedValueError extends TaggedError(
  "PbliteUnsupportedValueError",
)<{
  value: string;
  message: string;
}> {}

export type PbliteDecodeError =
  | PbliteJsonError
  | PbliteFieldError
  | PbliteUnsupportedFieldError;

export type PbliteEncodeError =
  | PbliteUnsupportedFieldError
  | PbliteUnsupportedValueError;

type ListField = Extract<DescField, { fieldKind: "list" }>;
type DecodedScalar = string | number | bigint | boolean | Uint8Array;
type FieldDecodeError = PbliteFieldError | PbliteUnsupportedFieldError;

const utf8Encoder = new TextEncoder();
// ignoreBOM keeps a leading U+FEFF, as Go's string(bytes) does.
const utf8Decoder = new TextDecoder("utf-8", { ignoreBOM: true });

const pbliteBinaryCache = new WeakMap<DescField, boolean>();

function isPbliteBinary(field: DescField): boolean {
  let value = pbliteBinaryCache.get(field);
  if (value === undefined) {
    value = getOption(field, pblite_binary);
    pbliteBinaryCache.set(field, value);
  }
  return value;
}

function fullName(field: DescField): string {
  return `${field.parent.typeName}.${field.name}`;
}

function scalarName(scalar: ScalarType): string {
  return ScalarType[scalar].toLowerCase();
}

function unsupportedField(
  field: DescField,
  fieldType: string,
): PbliteUnsupportedFieldError {
  const name = fullName(field);
  return new PbliteUnsupportedFieldError({
    field: name,
    fieldType,
    message: `pblite: field ${name} has type ${fieldType}, which pblite does not support (only int32/int64/uint32/uint64, float/double, bool, string, bytes, enums and messages are). The message cannot be converted; use binary protobuf for this type instead.`,
  });
}

function invariant(field: DescField, detail: string): Error {
  return new Error(
    `pblite: protobuf-es returned an unexpected value for field ${fullName(field)} (${detail}); this is a bug in the pblite codec`,
  );
}

const INT32_MIN = -2147483648;
const INT32_MAX = 2147483647;
const UINT32_MAX = 4294967295;

function maxFieldNumber(desc: DescMessage): number {
  let max = 0;
  for (const field of desc.fields) {
    if (field.number > max) max = field.number;
  }
  return max;
}

// ---------------------------------------------------------------------------
// Encoding

function serializeMessage(message: ReflectMessage): Pblite {
  const out: Pblite = new Array<PbliteValue>(maxFieldNumber(message.desc)).fill(
    null,
  );
  for (const field of message.fields) {
    if (!message.isSet(field)) continue;
    out[field.number - 1] = serializeField(message, field);
  }
  return out;
}

function serializeField(message: ReflectMessage, field: DescField): PbliteValue {
  switch (field.fieldKind) {
    case "list": {
      const items: PbliteValue[] = [];
      for (const item of message.get(field)) {
        items.push(serializeListItem(field, item));
      }
      return items;
    }
    case "map":
      throw unsupportedField(field, "map");
    case "message":
      return serializeMessageValue(
        field,
        field.delimitedEncoding,
        message.get(field),
      );
    case "enum":
      return serializeInteger(field, ScalarType.INT32, message.get(field));
    case "scalar":
      return serializeScalar(field, field.scalar, message.get(field));
  }
}

function serializeListItem(field: ListField, item: unknown): PbliteValue {
  switch (field.listKind) {
    case "message":
      if (!isReflectMessage(item, field.message)) {
        throw invariant(field, "list item is not a message");
      }
      return serializeMessageValue(field, field.delimitedEncoding, item);
    case "enum":
      if (typeof item !== "number") {
        throw invariant(field, "enum list item is not a number");
      }
      return serializeInteger(field, ScalarType.INT32, item);
    case "scalar":
      return serializeScalar(field, field.scalar, item);
  }
}

function serializeMessageValue(
  field: DescField,
  delimited: boolean,
  value: ReflectMessage,
): PbliteValue {
  if (delimited) throw unsupportedField(field, "group");
  if (isPbliteBinary(field)) {
    return base64Encode(toBinary(value.desc, value.message));
  }
  return serializeMessage(value);
}

function invalidInteger(
  field: DescField,
  scalar: ScalarType,
  value: number | bigint,
): PbliteUnsupportedValueError {
  const name = fullName(field);
  const isEnum =
    field.fieldKind === "enum" ||
    (field.fieldKind === "list" && field.listKind === "enum");
  const type = isEnum ? "enum (int32)" : scalarName(scalar);
  return new PbliteUnsupportedValueError({
    value: String(value),
    message: `pblite: field ${name} holds ${String(value)}, which is not a valid ${type} (Go cannot represent it, and binary protobuf rejects it too). Store a whole number within the ${type} range in this field.`,
  });
}

/**
 * 32-bit integers and enums as Go writes them: always whole numbers in range,
 * and never -0 (JS numbers can hold -0 in explicit-presence, oneof and
 * repeated fields; Go's integers cannot).
 */
function serializeInteger(
  field: DescField,
  scalar: ScalarType.INT32 | ScalarType.UINT32,
  value: number,
): number {
  if (scalar === ScalarType.UINT32) {
    if (!Number.isInteger(value) || value < 0 || value > UINT32_MAX) {
      throw invalidInteger(field, scalar, value);
    }
    return value >>> 0;
  }
  if (!Number.isInteger(value) || value < INT32_MIN || value > INT32_MAX) {
    throw invalidInteger(field, scalar, value);
  }
  return value | 0;
}

function serializeScalar(
  field: DescField,
  scalar: ScalarType,
  value: unknown,
): PbliteValue {
  switch (scalar) {
    case ScalarType.STRING:
      if (typeof value !== "string") break;
      return isPbliteBinary(field)
        ? base64Encode(utf8Encoder.encode(value))
        : value;
    case ScalarType.BYTES:
      if (!(value instanceof Uint8Array)) break;
      return base64Encode(value);
    case ScalarType.INT32:
    case ScalarType.UINT32:
      if (typeof value !== "number") break;
      return serializeInteger(field, scalar, value);
    case ScalarType.DOUBLE:
      if (typeof value !== "number") break;
      return value;
    case ScalarType.FLOAT:
      // Go widens the stored float32 to float64 before formatting.
      if (typeof value !== "number") break;
      return Math.fround(value);
    case ScalarType.INT64:
    case ScalarType.UINT64:
      // reflect returns bigint even for jstype=JS_STRING fields.
      if (typeof value !== "bigint") break;
      if (
        scalar === ScalarType.INT64
          ? BigInt.asIntN(64, value) !== value
          : BigInt.asUintN(64, value) !== value
      ) {
        throw invalidInteger(field, scalar, value);
      }
      return value;
    case ScalarType.BOOL:
      if (typeof value !== "boolean") break;
      return value;
    default:
      throw unsupportedField(field, scalarName(scalar));
  }
  throw invariant(field, `expected ${scalarName(scalar)}, got ${typeof value}`);
}

// encoding/json escapes these in strings (HTMLEscape and JS line separators).
const GO_EXTRA_ESCAPES = /[<>&\u2028\u2029]/g;

function goJsonString(value: string): string {
  // JSON.stringify escapes exactly the characters Go escapes (quote, backslash,
  // C0 controls with \b \f \n \r \t short forms, lowercase \u00xx otherwise)
  // apart from GO_EXTRA_ESCAPES. Lone surrogates become U+FFFD, which is what
  // Go would see after the string round-trips through UTF-8.
  return JSON.stringify(value.toWellFormed()).replace(
    GO_EXTRA_ESCAPES,
    (char) => `\\u${char.charCodeAt(0).toString(16).padStart(4, "0")}`,
  );
}

function goJsonNumber(value: number): string {
  if (!Number.isFinite(value)) {
    throw new PbliteUnsupportedValueError({
      value: String(value),
      message: `pblite: cannot encode ${String(value)} in JSON (Go's encoding/json rejects it too). Make sure float and double fields hold finite numbers.`,
    });
  }
  // Go and ECMAScript both print the shortest round-trip form and switch to
  // exponent notation below 1e-6 and from 1e21 (e.g. 1e-7, 1e+21); only the
  // sign of zero differs.
  return Object.is(value, -0) ? "-0" : String(value);
}

function goJson(value: PbliteValue): string {
  if (value === null) return "null";
  if (typeof value === "boolean") return value ? "true" : "false";
  if (typeof value === "bigint") return value.toString();
  if (typeof value === "number") return goJsonNumber(value);
  if (typeof value === "string") return goJsonString(value);
  return `[${value.map(goJson).join(",")}]`;
}

/**
 * Converts a message to its pblite array (Go `SerializeToSlice`). 64-bit
 * integers are bigint, so use `marshal` for JSON text.
 *
 * @throws PbliteUnsupportedFieldError when a set field has a kind pblite
 *   cannot represent (map, group, sint32/64, fixed32/64, sfixed32/64).
 * @throws PbliteUnsupportedValueError when an integer or enum field holds a
 *   fraction or a value outside its type's range.
 */
function serialize<Desc extends DescMessage>(
  schema: Desc,
  message: MessageShape<Desc>,
): Pblite {
  return serializeMessage(reflect(schema, message));
}

/**
 * Encodes a message as pblite JSON text, byte-identical to Go `pblite.Marshal`.
 *
 * @throws PbliteUnsupportedFieldError as for `serialize`.
 * @throws PbliteUnsupportedValueError as for `serialize`, and when a float or
 *   double is NaN or ±Infinity.
 */
function marshal<Desc extends DescMessage>(
  schema: Desc,
  message: MessageShape<Desc>,
): string {
  return goJson(serialize(schema, message));
}

// ---------------------------------------------------------------------------
// Decoding

function isArray(value: unknown): value is readonly unknown[] {
  return Array.isArray(value);
}

function jsonTypeName(value: unknown): string {
  if (value === null) return "null";
  if (isArray(value)) return "array";
  return typeof value;
}

function fieldError(
  field: DescField,
  index: number,
  expected: string,
  value: unknown,
  cause?: unknown,
): PbliteFieldError {
  const name = fullName(field);
  const got = jsonTypeName(value);
  return new PbliteFieldError({
    field: name,
    index,
    expected,
    got,
    message: `pblite: expected ${expected} at index ${index} for field ${name}, got ${got}. The message was not decoded; the payload does not match the ${field.parent.typeName} schema.`,
    cause,
  });
}

function parseJsonArray(text: string): Result<readonly unknown[], PbliteJsonError> {
  let nonFinite = false;
  let parsed: unknown;
  try {
    parsed = JSON.parse(text, (_key: string, value: unknown) => {
      if (typeof value === "number" && !Number.isFinite(value)) nonFinite = true;
      return value;
    });
  } catch {
    // The SyntaxError is dropped on purpose: engines quote part of the input
    // in its message, and pblite bodies carry tokens.
    return Result.err(
      new PbliteJsonError({
        message: `pblite: input (${text.length} characters) is not valid JSON, so no message was decoded. Check that the response body is complete and is pblite, not binary protobuf.`,
      }),
    );
  }
  if (nonFinite) {
    // Go's encoding/json fails on numbers that overflow float64 (e.g. 1e400).
    return Result.err(
      new PbliteJsonError({
        message:
          "pblite: input contains a JSON number outside the float64 range, so no message was decoded.",
      }),
    );
  }
  if (!isArray(parsed)) {
    return Result.err(
      new PbliteJsonError({
        message: `pblite: expected a JSON array at the top level, got ${jsonTypeName(parsed)}, so no message was decoded.`,
      }),
    );
  }
  return Result.ok(parsed);
}

/** Go base64.StdEncoding.DecodeString: padded std alphabet, CR/LF ignored. */
function decodeStdBase64(input: string): Uint8Array | undefined {
  const text = /[\r\n]/.test(input) ? input.replace(/[\r\n]/g, "") : input;
  if (text.length % 4 !== 0) return undefined;
  const padding = text.endsWith("==") ? 2 : text.endsWith("=") ? 1 : 0;
  for (let i = 0; i < text.length - padding; i++) {
    const c = text.charCodeAt(i);
    const valid =
      (c >= 65 && c <= 90) || // A-Z
      (c >= 97 && c <= 122) || // a-z
      (c >= 48 && c <= 57) || // 0-9
      c === 43 || // +
      c === 47; // /
    if (!valid) return undefined;
  }
  return base64Decode(text);
}

const INT64_MIN = -(1n << 63n);
const TWO_POW_63 = 1n << 63n;

/** Go strconv.ParseInt / ParseUint with base 10 and the given bit size. */
function parseDecimal(
  text: string,
  signed: boolean,
  bits: 32 | 64,
): bigint | undefined {
  if (!(signed ? /^[+-]?[0-9]+$/ : /^[0-9]+$/).test(text)) return undefined;
  const value = BigInt(text.startsWith("+") ? text.slice(1) : text);
  const fits = signed
    ? BigInt.asIntN(bits, value) === value
    : BigInt.asUintN(bits, value) === value;
  return fits ? value : undefined;
}

// Go float64 -> integer conversions. In range they truncate toward zero; out
// of range the Go spec leaves the result implementation-defined, and these
// reproduce amd64 (CVTTSD2SL/CVTTSD2SQ return the minimum signed value).
function int32FromFloat(value: number): number {
  const truncated = Math.trunc(value);
  return truncated >= INT32_MIN && truncated <= INT32_MAX
    ? truncated | 0
    : INT32_MIN;
}

function int64FromFloat(value: number): bigint {
  if (!Number.isFinite(value)) return INT64_MIN;
  const truncated = BigInt(Math.trunc(value));
  return BigInt.asIntN(64, truncated) === truncated ? truncated : INT64_MIN;
}

function uint32FromFloat(value: number): number {
  return Number(BigInt.asUintN(32, int64FromFloat(value)));
}

function uint64FromFloat(value: number): bigint {
  if (value < 2 ** 63) return BigInt.asUintN(64, int64FromFloat(value));
  return BigInt.asUintN(64, int64FromFloat(value - 2 ** 63)) | TWO_POW_63;
}

function decodeInteger(
  field: DescField,
  scalar: ScalarType.INT32 | ScalarType.INT64 | ScalarType.UINT32 | ScalarType.UINT64,
  value: unknown,
  index: number,
): Result<number | bigint, PbliteFieldError> {
  const signed = scalar === ScalarType.INT32 || scalar === ScalarType.INT64;
  const bits = scalar === ScalarType.INT32 || scalar === ScalarType.UINT32 ? 32 : 64;
  const name = scalarName(scalar);
  const toResult = (parsed: bigint): number | bigint =>
    bits === 32 ? Number(parsed) : parsed;

  if (typeof value === "string") {
    const parsed = parseDecimal(value, signed, bits);
    return parsed === undefined
      ? Result.err(
          fieldError(field, index, `${name} decimal string within range`, value),
        )
      : Result.ok(toResult(parsed));
  }
  if (typeof value === "number") {
    switch (scalar) {
      case ScalarType.INT32:
        return Result.ok(int32FromFloat(value));
      case ScalarType.INT64:
        return Result.ok(int64FromFloat(value));
      case ScalarType.UINT32:
        return Result.ok(uint32FromFloat(value));
      case ScalarType.UINT64:
        return Result.ok(uint64FromFloat(value));
    }
  }
  // bigint never comes from JSON; accepting it lets serialize() output be
  // decoded directly.
  if (typeof value === "bigint") {
    const fits = signed
      ? BigInt.asIntN(bits, value) === value
      : BigInt.asUintN(bits, value) === value;
    if (fits) return Result.ok(toResult(value));
  }
  return Result.err(
    fieldError(field, index, `${name} as a JSON number or decimal string`, value),
  );
}

function decodeScalar(
  field: DescField,
  scalar: ScalarType,
  value: unknown,
  index: number,
): Result<DecodedScalar, FieldDecodeError> {
  switch (scalar) {
    case ScalarType.INT32:
    case ScalarType.INT64:
    case ScalarType.UINT32:
    case ScalarType.UINT64:
      return decodeInteger(field, scalar, value, index);
    case ScalarType.FLOAT:
      return typeof value === "number"
        ? Result.ok(Math.fround(value))
        : Result.err(fieldError(field, index, "number", value));
    case ScalarType.DOUBLE:
      return typeof value === "number"
        ? Result.ok(value)
        : Result.err(fieldError(field, index, "number", value));
    case ScalarType.BOOL:
      if (typeof value === "boolean") return Result.ok(value);
      if (typeof value === "number") return Result.ok(value !== 0);
      return Result.err(fieldError(field, index, "bool or number", value));
    case ScalarType.STRING: {
      if (typeof value !== "string") {
        return Result.err(fieldError(field, index, "string", value));
      }
      if (!isPbliteBinary(field)) return Result.ok(value.toWellFormed());
      const bytes = decodeStdBase64(value);
      return bytes === undefined
        ? Result.err(fieldError(field, index, "base64 (std, padded) string", value))
        : Result.ok(utf8Decoder.decode(bytes));
    }
    case ScalarType.BYTES: {
      if (typeof value !== "string") {
        return Result.err(fieldError(field, index, "base64 string", value));
      }
      const bytes = decodeStdBase64(value);
      return bytes === undefined
        ? Result.err(fieldError(field, index, "base64 (std, padded) string", value))
        : Result.ok(bytes);
    }
    default:
      return Result.err(unsupportedField(field, scalarName(scalar)));
  }
}

function decodeEnum(
  field: DescField,
  value: unknown,
  index: number,
): Result<number, PbliteFieldError> {
  return typeof value === "number"
    ? Result.ok(int32FromFloat(value))
    : Result.err(fieldError(field, index, "enum number", value));
}

function decodeMessageValue(
  field: DescField,
  desc: DescMessage,
  delimited: boolean,
  value: unknown,
  index: number,
): Result<ReflectMessage, PbliteDecodeError> {
  if (delimited) return Result.err(unsupportedField(field, "group"));
  if (isPbliteBinary(field)) {
    if (typeof value !== "string") {
      return Result.err(fieldError(field, index, "base64 string", value));
    }
    const bytes = decodeStdBase64(value);
    if (bytes === undefined) {
      return Result.err(
        fieldError(field, index, "base64 (std, padded) string", value),
      );
    }
    try {
      return Result.ok(reflect(desc, fromBinary(desc, bytes)));
    } catch (cause) {
      return Result.err(
        fieldError(field, index, `base64 of a binary ${desc.typeName}`, value, cause),
      );
    }
  }
  if (!isArray(value)) {
    return Result.err(fieldError(field, index, "array (message)", value));
  }
  const nested = reflect(desc);
  const decoded = deserializeMessage(nested, value);
  return decoded.isErr() ? Result.err(decoded.error) : Result.ok(nested);
}

function decodeListItem(
  field: ListField,
  value: unknown,
  index: number,
): Result<unknown, PbliteDecodeError> {
  switch (field.listKind) {
    case "message":
      return decodeMessageValue(
        field,
        field.message,
        field.delimitedEncoding,
        value,
        index,
      );
    case "enum":
      return decodeEnum(field, value, index);
    case "scalar":
      return decodeScalar(field, field.scalar, value, index);
  }
}

function deserializeField(
  message: ReflectMessage,
  field: DescField,
  value: unknown,
  index: number,
): Result<void, PbliteDecodeError> {
  let decoded: Result<unknown, PbliteDecodeError>;
  switch (field.fieldKind) {
    case "list": {
      if (!isArray(value)) {
        return Result.err(fieldError(field, index, "array (repeated field)", value));
      }
      const list = reflectList(field);
      for (let i = 0; i < value.length; i++) {
        // Unlike top-level fields, null list elements are errors in Go.
        const item = decodeListItem(field, value[i] ?? null, i);
        if (item.isErr()) return Result.err(item.error);
        list.add(item.value);
      }
      decoded = Result.ok(list);
      break;
    }
    case "map":
      return Result.err(unsupportedField(field, "map"));
    case "message":
      decoded = decodeMessageValue(
        field,
        field.message,
        field.delimitedEncoding,
        value,
        index,
      );
      break;
    case "enum":
      decoded = decodeEnum(field, value, index);
      break;
    case "scalar":
      decoded = decodeScalar(field, field.scalar, value, index);
      break;
  }
  if (decoded.isErr()) return Result.err(decoded.error);
  message.set(field, decoded.value);
  return Result.ok();
}

function deserializeMessage(
  message: ReflectMessage,
  data: readonly unknown[],
): Result<void, PbliteDecodeError> {
  // Declaration order, like Go: the first bad field is reported, and the last
  // member of a oneof present in the input wins.
  for (const field of message.fields) {
    const index = field.number - 1;
    if (index >= data.length) continue;
    const value = data[index];
    if (value === null || value === undefined) continue;
    const result = deserializeField(message, field, value, index);
    if (result.isErr()) return result;
  }
  return Result.ok();
}

/**
 * Decodes pblite (Go `pblite.Unmarshal`). `input` is JSON text or an already
 * parsed array (for example one element of a long-poll stream).
 */
function unmarshal<Desc extends DescMessage>(
  schema: Desc,
  input: string | readonly unknown[],
): Result<MessageShape<Desc>, PbliteDecodeError> {
  let data: readonly unknown[];
  if (typeof input === "string") {
    const parsed = parseJsonArray(input);
    if (parsed.isErr()) return Result.err(parsed.error);
    data = parsed.value;
  } else {
    data = input;
  }
  const message = create(schema);
  const decoded = deserializeMessage(reflect(schema, message), data);
  return decoded.isErr() ? Result.err(decoded.error) : Result.ok(message);
}

export const Pblite = {
  serialize,
  marshal,
  unmarshal,
} as const;
